INSERT INTO `visa_faqs` (`id`, `question`, `answer`, `country_id`, `visa_type_id`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (1,'Do I need a visa to travel abroad?','Visa requirements depend on your nationality, destination country, and purpose of travel. Use the visa search tool to check requirements for your specific situation.',NULL,NULL,1,1,'2026-08-12 20:32:06','2026-08-12 20:32:06');
INSERT INTO `visa_faqs` (`id`, `question`, `answer`, `country_id`, `visa_type_id`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (2,'How long does visa processing take?','Processing times vary significantly by country, visa type, and application volume. Each visa\'s detail page lists the current processing time as last verified, along with its source.',NULL,NULL,2,1,'2026-08-12 20:32:06','2026-08-12 20:32:06');
INSERT INTO `visa_faqs` (`id`, `question`, `answer`, `country_id`, `visa_type_id`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (3,'What documents do I typically need for a visa application?','Common documents include a valid passport, passport-size photographs, proof of financial means, and travel or accommodation details. Exact requirements vary by country and visa type — see the specific visa page for the full checklist.',NULL,NULL,3,1,'2026-08-12 20:32:06','2026-08-12 20:32:06');
INSERT INTO `visa_faqs` (`id`, `question`, `answer`, `country_id`, `visa_type_id`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (4,'Can Visagiri guarantee my visa will be approved?','No. Visa decisions are made solely by the relevant embassy, consulate, or government immigration authority. Visagiri assists with preparation, documentation, and application management, but cannot guarantee approval outcomes.',NULL,NULL,4,1,'2026-08-12 20:32:06','2026-08-12 20:32:06');
INSERT INTO `visa_faqs` (`id`, `question`, `answer`, `country_id`, `visa_type_id`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (5,'How can I track my visa application?','Once your application is submitted, your assigned consultant keeps you updated directly — reach out any time via WhatsApp, call, or the enquiry form for the latest status.',NULL,NULL,5,1,'2026-08-12 20:32:06','2026-08-12 20:32:06');
